// Extra practical rounds: each row is a complete prompt with a Vietnamese explanation.
const interview = [
  ['Can you walk me through your experience as a backend developer?', 'Bạn có thể kể về kinh nghiệm làm backend của mình không?', 'Nhà tuyển dụng muốn nghe phần việc và phạm vi trách nhiệm của bạn trong dự án gần đây.', 'I have worked mainly on Java and Spring Boot services for business applications. My responsibilities include designing REST APIs, implementing business rules, writing database queries, and fixing production issues. I also work with frontend, QA, and product teammates to deliver features from requirement clarification through release.', 'Tôi chủ yếu làm các dịch vụ Java và Spring Boot cho ứng dụng nghiệp vụ. Công việc của tôi gồm thiết kế REST API, triển khai quy tắc nghiệp vụ, viết truy vấn cơ sở dữ liệu và xử lý lỗi production. Tôi cũng phối hợp với frontend, QA và product từ lúc làm rõ yêu cầu đến khi phát hành.', ['Nêu lĩnh vực và công nghệ chính', 'Kể trách nhiệm trực tiếp', 'Nêu cách phối hợp để bàn giao tính năng'], [['business application', 'ứng dụng nghiệp vụ'], ['implement a business rule', 'triển khai quy tắc nghiệp vụ'], ['deliver a feature', 'bàn giao một tính năng']]],
  ['What was your role in your most recent project?', 'Vai trò của bạn trong dự án gần đây nhất là gì?', 'Bạn làm ở nhóm phát triển một hệ thống quản lý đơn hàng cho khách hàng quốc tế.', 'I was a backend developer on the order management team. I implemented endpoints for order search and status updates, added validation and authorization, and worked with QA to cover edge cases. I also reviewed pull requests and helped investigate issues in staging and production.', 'Tôi là backend developer trong nhóm quản lý đơn hàng. Tôi triển khai endpoint tìm kiếm và cập nhật trạng thái đơn, thêm validation và phân quyền, đồng thời phối hợp với QA kiểm tra các trường hợp biên. Tôi cũng review pull request và hỗ trợ điều tra lỗi ở staging và production.', ['Nêu vai trò trong nhóm', 'Đưa ra hai đầu việc cụ thể', 'Kết thúc bằng trách nhiệm chất lượng hoặc phối hợp'], [['edge case', 'trường hợp biên'], ['authorization', 'phân quyền truy cập'], ['investigate an issue', 'điều tra sự cố']]],
  ['How do you validate incoming API requests?', 'Bạn kiểm tra request gửi vào API như thế nào?', 'Bạn được hỏi về validation cho endpoint tạo đơn hàng.', 'I validate the request at the API boundary using a request DTO and bean validation annotations. The service still checks business rules, such as whether the customer can place an order. If the input is invalid, a global exception handler returns a consistent 400 response with field-level errors.', 'Tôi kiểm tra request tại ranh giới API bằng request DTO và các annotation bean validation. Service vẫn kiểm tra quy tắc nghiệp vụ, chẳng hạn khách hàng có được đặt đơn hay không. Nếu dữ liệu không hợp lệ, global exception handler trả về response 400 thống nhất kèm lỗi theo từng field.', ['Nêu DTO và validation ở tầng API', 'Phân biệt validation dữ liệu và quy tắc nghiệp vụ', 'Nêu phản hồi lỗi nhất quán'], [['API boundary', 'ranh giới tiếp nhận của API'], ['bean validation', 'cơ chế kiểm tra dữ liệu bằng annotation'], ['field-level error', 'lỗi gắn với từng field']]],
  ['When would you use a database transaction?', 'Khi nào bạn dùng transaction cơ sở dữ liệu?', 'Một thao tác thanh toán cần cập nhật đơn hàng và ghi nhận giao dịch trong cùng quy trình.', 'I use a transaction when several database changes must succeed or fail together. For example, confirming a payment may update the order and save a payment record. The transaction keeps those changes consistent. I keep the transactional boundary focused and avoid holding a database transaction open while calling a slow external service.', 'Tôi dùng transaction khi nhiều thay đổi cơ sở dữ liệu phải cùng thành công hoặc cùng thất bại. Ví dụ, xác nhận thanh toán có thể cập nhật đơn hàng và lưu bản ghi thanh toán. Transaction giúp các thay đổi đó nhất quán. Tôi giữ phạm vi transaction gọn và tránh mở transaction trong lúc gọi dịch vụ ngoài chậm.', ['Giải thích tính nguyên tử của thay đổi', 'Nêu ví dụ nghiệp vụ', 'Nói cách giữ phạm vi transaction hợp lý'], [['succeed or fail together', 'cùng thành công hoặc cùng thất bại'], ['transactional boundary', 'ranh giới xử lý của transaction'], ['consistent', 'nhất quán']]],
  ['How do you handle exceptions in a REST API?', 'Bạn xử lý exception trong REST API như thế nào?', 'Nhà tuyển dụng muốn biết cách API không trả lỗi nội bộ khó hiểu cho client.', 'I handle known business errors with specific exceptions and map them to suitable HTTP status codes. A global exception handler formats the response consistently and logs unexpected errors with a correlation ID. I avoid returning stack traces or sensitive details to the client.', 'Tôi dùng exception cụ thể cho lỗi nghiệp vụ đã biết và ánh xạ chúng sang HTTP status code phù hợp. Global exception handler định dạng response thống nhất và ghi log lỗi bất ngờ kèm correlation ID. Tôi không trả stack trace hoặc thông tin nhạy cảm cho client.', ['Nêu lỗi nghiệp vụ và status code', 'Giải thích global handler và logging', 'Nhắc bảo vệ thông tin nội bộ'], [['map to a status code', 'ánh xạ sang mã trạng thái'], ['correlation ID', 'mã định danh để theo dõi xuyên suốt request'], ['sensitive detail', 'thông tin nhạy cảm']]],
  ['How do you test a service that depends on a repository?', 'Bạn kiểm thử service phụ thuộc repository như thế nào?', 'Service tính tổng tiền đơn hàng, còn repository đọc thông tin sản phẩm từ database.', 'For a unit test, I mock the repository so I can focus on the service business rules and verify how it handles returned data or errors. I add repository integration tests separately to check the actual query and database mapping. This gives fast feedback without relying on one kind of test for everything.', 'Trong unit test, tôi mock repository để tập trung vào quy tắc nghiệp vụ của service và kiểm tra cách service xử lý dữ liệu hoặc lỗi trả về. Tôi viết riêng integration test cho repository để kiểm tra truy vấn thật và mapping cơ sở dữ liệu. Như vậy có phản hồi nhanh mà không phụ thuộc một loại test cho mọi thứ.', ['Phân biệt unit test và integration test', 'Nêu điều cần kiểm tra ở service', 'Nêu điều cần kiểm tra ở repository'], [['mock a dependency', 'giả lập dependency'], ['business rule', 'quy tắc nghiệp vụ'], ['database mapping', 'ánh xạ dữ liệu cơ sở dữ liệu']]],
  ['How do you avoid the N+1 query problem?', 'Bạn tránh vấn đề N+1 query như thế nào?', 'Trang đơn hàng hiển thị tên khách hàng cho từng đơn và đang phát sinh quá nhiều truy vấn.', 'I first confirm the issue by checking SQL logs or query metrics. Then I choose a solution based on the use case, such as a fetch join, an entity graph, or a projection DTO. I check the generated SQL and result size because fetching too much related data can create a different performance problem.', 'Tôi xác nhận vấn đề bằng SQL log hoặc query metrics trước. Sau đó chọn cách xử lý theo use case, như fetch join, entity graph hoặc projection DTO. Tôi kiểm tra SQL được sinh ra và kích thước kết quả vì lấy quá nhiều dữ liệu liên quan có thể tạo ra vấn đề hiệu năng khác.', ['Nêu cách xác nhận bằng chứng', 'Đưa ra các lựa chọn phù hợp', 'Nhắc kiểm tra SQL và kích thước dữ liệu'], [['fetch join', 'join để tải dữ liệu liên quan cùng truy vấn'], ['projection DTO', 'DTO chỉ chứa các trường cần truy vấn'], ['generated SQL', 'câu SQL được framework tạo ra']]],
  ['What is the difference between an entity and a DTO?', 'Entity và DTO khác nhau thế nào?', 'Bạn cần giải thích vì sao API không trả trực tiếp JPA entity.', 'An entity represents persisted data and is managed by the persistence context. A DTO represents data exchanged across an API boundary. I map between them so the API contract does not depend on database details, and I can control which fields are exposed. For simple mappings I may use MapStruct to generate repetitive code.', 'Entity đại diện cho dữ liệu được lưu và được persistence context quản lý. DTO đại diện cho dữ liệu trao đổi qua ranh giới API. Tôi mapping giữa chúng để contract API không phụ thuộc chi tiết database và để kiểm soát field được trả ra. Với mapping đơn giản, tôi có thể dùng MapStruct sinh phần code lặp.', ['Định nghĩa entity theo persistence', 'Định nghĩa DTO theo API', 'Nêu lý do mapping và vai trò MapStruct'], [['persistence context', 'ngữ cảnh quản lý entity của JPA'], ['API contract', 'quy ước dữ liệu giữa API và client'], ['expose a field', 'đưa một trường dữ liệu ra bên ngoài']]],
  ['How do you secure a REST API?', 'Bạn bảo vệ REST API như thế nào?', 'API có endpoint cho user đăng nhập và endpoint chỉ admin được gọi.', 'I authenticate the caller, usually with a validated token, and authorize each operation based on roles or permissions. I also validate input, avoid exposing sensitive fields, and keep secrets outside source code. For sensitive actions, I make sure the access rules are enforced on the server, not only hidden in the UI.', 'Tôi xác thực người gọi, thường bằng token đã được kiểm tra, rồi phân quyền từng thao tác theo role hoặc permission. Tôi cũng validate dữ liệu, tránh lộ field nhạy cảm và không để secret trong source code. Với thao tác nhạy cảm, tôi đảm bảo quyền được kiểm tra ở server chứ không chỉ ẩn trên UI.', ['Phân biệt authentication và authorization', 'Nêu validation và bảo vệ dữ liệu', 'Nhấn mạnh kiểm tra quyền ở server'], [['authenticate', 'xác minh danh tính'], ['authorize', 'kiểm tra quyền thực hiện hành động'], ['enforce a rule', 'bắt buộc áp dụng một quy tắc']]],
  ['How do you handle database schema changes?', 'Bạn xử lý thay đổi schema database như thế nào?', 'Một tính năng mới cần thêm cột trạng thái nhưng hệ thống đang chạy nhiều phiên bản ứng dụng.', 'I manage schema changes with versioned migration scripts and review them with the application change. For a backward-compatible rollout, I add the new column first, deploy code that can handle both states, and backfill data if needed. I also plan how to monitor and roll back the change.', 'Tôi quản lý thay đổi schema bằng migration script có version và review cùng thay đổi ứng dụng. Để triển khai tương thích ngược, tôi thêm cột trước, deploy code xử lý được cả hai trạng thái rồi cập nhật dữ liệu cũ nếu cần. Tôi cũng lên kế hoạch theo dõi và rollback.', ['Giải thích migration có version', 'Nêu thứ tự triển khai tương thích ngược', 'Nêu theo dõi và phương án quay lại'], [['schema migration', 'thay đổi cấu trúc database có quản lý phiên bản'], ['backward-compatible', 'tương thích với phiên bản cũ'], ['backfill data', 'cập nhật dữ liệu đã tồn tại']]],
  ['How do you investigate a slow SQL query?', 'Bạn điều tra một truy vấn SQL chậm như thế nào?', 'API tìm kiếm có dấu hiệu chậm hơn sau khi dữ liệu tăng lên.', 'I reproduce the query with realistic parameters and inspect its execution plan. I check whether indexes are used, how many rows are scanned, and whether joins or sorting are expensive. After making a targeted change, I compare the query time and verify that the result is still correct.', 'Tôi tái hiện truy vấn với tham số thực tế và xem execution plan. Tôi kiểm tra index có được dùng không, số hàng bị quét và join hoặc sort có tốn kém không. Sau khi thay đổi đúng mục tiêu, tôi so sánh thời gian truy vấn và xác nhận kết quả vẫn chính xác.', ['Nêu cách tái hiện và xem execution plan', 'Kể các dấu hiệu cần kiểm tra', 'Đo lại và kiểm tra tính đúng'], [['rows scanned', 'số hàng bị quét'], ['expensive sort', 'thao tác sắp xếp tốn tài nguyên'], ['targeted change', 'thay đổi tập trung vào nguyên nhân']]],
  ['What do you consider when designing a REST endpoint?', 'Bạn cân nhắc điều gì khi thiết kế REST endpoint?', 'Bạn thiết kế endpoint cho danh sách đơn có lọc, sắp xếp và phân trang.', 'I start with the resource and the client use case. I use clear HTTP methods and status codes, validate filters, and define predictable pagination and sorting. I document the request and response shape, including error cases. I also consider authorization and how the endpoint will behave with large datasets.', 'Tôi bắt đầu từ resource và use case của client. Tôi dùng HTTP method và status code rõ ràng, validate bộ lọc và định nghĩa phân trang, sắp xếp có thể dự đoán. Tôi mô tả request, response và các trường hợp lỗi. Tôi cũng cân nhắc phân quyền và cách endpoint hoạt động với dữ liệu lớn.', ['Bắt đầu từ resource và use case', 'Nêu method, status, filter, pagination', 'Nêu tài liệu, quyền và dữ liệu lớn'], [['resource', 'đối tượng nghiệp vụ API cung cấp'], ['predictable pagination', 'phân trang có quy tắc nhất quán'], ['response shape', 'cấu trúc dữ liệu trả về']]],
  ['How do you work with an international client remotely?', 'Bạn làm việc từ xa với khách hàng quốc tế như thế nào?', 'Khách hàng ở múi giờ khác và yêu cầu thường được trao đổi qua cuộc họp, ticket và tài liệu.', 'I prepare questions before meetings and summarize decisions afterward in writing. When a requirement is unclear, I confirm the expected behavior and acceptance criteria instead of making assumptions. I keep tickets updated, raise risks early, and share concise progress updates so the client can follow the work asynchronously.', 'Tôi chuẩn bị câu hỏi trước cuộc họp và ghi lại quyết định sau đó. Khi yêu cầu chưa rõ, tôi xác nhận hành vi mong muốn và tiêu chí nghiệm thu thay vì tự giả định. Tôi cập nhật ticket, báo rủi ro sớm và gửi tiến độ ngắn gọn để khách hàng theo dõi công việc không đồng bộ.', ['Chuẩn bị và ghi lại quyết định', 'Làm rõ kỳ vọng thay vì tự đoán', 'Cập nhật ticket và báo rủi ro sớm'], [['acceptance criteria', 'tiêu chí nghiệm thu'], ['raise a risk', 'chủ động báo rủi ro'], ['asynchronously', 'không cần hai bên cùng trực tuyến một lúc']]],
  ['What do you do when a deployment fails?', 'Bạn làm gì khi một lần deploy thất bại?', 'Pipeline đã build thành công nhưng health check của môi trường staging không qua.', 'I check the deployment logs and health check details first, then compare the change with the last successful release. I look at configuration, secrets, and application startup errors. If the environment is affected, I follow the rollback procedure and communicate the impact. Afterward, I document the root cause and add a preventive check if possible.', 'Tôi kiểm tra log deploy và chi tiết health check trước, rồi so sánh thay đổi với lần phát hành thành công gần nhất. Tôi xem cấu hình, secret và lỗi khởi động ứng dụng. Nếu môi trường bị ảnh hưởng, tôi làm theo quy trình rollback và thông báo tác động. Sau đó tôi ghi nhận nguyên nhân gốc và thêm bước kiểm tra phòng ngừa nếu có thể.', ['Xem log và so sánh bản phát hành', 'Rollback và thông báo tác động khi cần', 'Ghi nguyên nhân và biện pháp phòng ngừa'], [['health check', 'kiểm tra ứng dụng có hoạt động bình thường'], ['root cause', 'nguyên nhân gốc'], ['preventive check', 'bước kiểm tra để ngăn lỗi lặp lại']]],
  ['How do you handle competing priorities?', 'Bạn xử lý nhiều việc ưu tiên cùng lúc như thế nào?', 'Bạn vừa có lỗi production vừa có task tính năng sắp đến hạn.', 'I compare the customer impact, urgency, and dependencies with the product owner or team lead. I explain the trade-offs and agree on what should be handled first. If I switch to the production issue, I update the feature estimate and keep the stakeholders informed instead of silently missing the deadline.', 'Tôi so sánh mức ảnh hưởng tới khách hàng, độ khẩn cấp và dependency với product owner hoặc team lead. Tôi giải thích các đánh đổi và thống nhất việc nào cần làm trước. Nếu chuyển sang xử lý production, tôi cập nhật ước lượng tính năng và thông báo cho các bên liên quan thay vì im lặng trễ hạn.', ['Nêu tiêu chí ưu tiên', 'Thống nhất thứ tự với nhóm', 'Cập nhật tiến độ và tác động'], [['customer impact', 'mức ảnh hưởng đến khách hàng'], ['trade-off', 'sự đánh đổi'], ['stakeholder', 'bên liên quan']]],
];

const standup = [
  ['Hôm qua bạn thêm phân trang cho API tìm kiếm đơn. Hôm nay bạn tối ưu sort theo ngày tạo. Không có blocker.', 'I added pagination to the order search API yesterday.', 'Today, I’m optimizing the sort by creation date.', 'I don’t have any blockers right now.', ['Hôm qua tôi đã thêm phân trang cho API tìm kiếm đơn.', 'Hôm nay tôi đang tối ưu sắp xếp theo ngày tạo.', 'Hiện tại tôi không có vướng mắc nào.'], [['pagination', 'phân trang'], ['sort by', 'sắp xếp theo'], ['right now', 'ngay lúc này']]],
  ['Hôm qua bạn thêm kiểm tra quyền admin cho API export. Hôm nay bạn sẽ bổ sung test cho user thường. Bạn đang chờ product xác nhận thông báo lỗi.', 'I added the admin permission check to the export API.', 'Today, I’m adding tests for regular users.', 'I’m waiting for Product to confirm the error message.', ['Hôm qua tôi đã thêm kiểm tra quyền admin cho API export.', 'Hôm nay tôi đang thêm test cho user thông thường.', 'Tôi đang chờ Product xác nhận thông báo lỗi.'], [['permission check', 'kiểm tra quyền'], ['regular user', 'người dùng thông thường'], ['confirm the error message', 'xác nhận nội dung thông báo lỗi']]],
  ['Hôm qua bạn sửa lỗi null pointer ở luồng cập nhật profile. Hôm nay bạn chạy regression test. QA đang kiểm tra một lỗi khác nên chưa retest được.', 'I fixed a null pointer issue in the profile update flow.', 'Today, I’m running the regression tests.', 'QA is investigating another issue, so they haven’t been able to retest this change yet.', ['Tôi đã sửa lỗi null pointer ở luồng cập nhật hồ sơ.', 'Hôm nay tôi đang chạy regression test.', 'QA đang điều tra lỗi khác nên chưa thể kiểm thử lại thay đổi này.'], [['profile update flow', 'luồng cập nhật hồ sơ'], ['regression test', 'kiểm thử phát hiện lỗi quay lại'], ['retest', 'kiểm thử lại']]],
  ['Hôm qua bạn tạo dashboard theo dõi lỗi 5xx. Hôm nay bạn kiểm tra alert trên staging. Bạn chưa được cấp quyền xem CloudWatch.', 'I created a dashboard to track 5xx errors.', 'Today, I’m checking the alert in staging.', 'I’m blocked because I don’t have access to CloudWatch yet.', ['Tôi đã tạo dashboard theo dõi lỗi 5xx.', 'Hôm nay tôi đang kiểm tra alert trên staging.', 'Tôi đang bị vướng vì chưa có quyền truy cập CloudWatch.'], [['track errors', 'theo dõi lỗi'], ['alert', 'cảnh báo tự động'], ['be blocked because', 'bị vướng vì']]],
  ['Hôm qua bạn hoàn tất API upload avatar lên S3. Hôm nay bạn thêm giới hạn kích thước file. Bạn cần khách hàng xác nhận định dạng được hỗ trợ.', 'I finished the avatar upload API using S3.', 'Today, I’m adding a file size limit.', 'I need the client to confirm which file formats should be supported.', ['Hôm qua tôi đã hoàn thành API tải avatar lên S3.', 'Hôm nay tôi đang thêm giới hạn dung lượng file.', 'Tôi cần khách hàng xác nhận các định dạng file được hỗ trợ.'], [['file size limit', 'giới hạn dung lượng file'], ['file format', 'định dạng file'], ['be supported', 'được hỗ trợ']]],
  ['Hôm qua bạn thay derived query bằng @Query vì điều kiện lọc phức tạp. Hôm nay bạn so sánh kết quả và query plan. Không có blocker.', 'I replaced the derived query with an @Query because the filter logic was complex.', 'Today, I’m comparing the results and the query plan.', 'I don’t have any blockers. I’ll share the measurements in the pull request.', ['Tôi thay derived query bằng @Query vì logic lọc phức tạp.', 'Hôm nay tôi đang so sánh kết quả và query plan.', 'Tôi không có vướng mắc. Tôi sẽ chia sẻ số liệu trong pull request.'], [['derived query', 'truy vấn được suy ra từ tên method'], ['filter logic', 'logic lọc dữ liệu'], ['share the measurements', 'chia sẻ các số liệu đo được']]],
  ['Hôm qua bạn thêm MapStruct mapping cho nested DTO. Hôm nay bạn kiểm tra generated implementation. Một build agent đang offline.', 'I added MapStruct mapping for the nested DTO.', 'Today, I’m reviewing the generated implementation.', 'The build is blocked because one of our build agents is offline.', ['Hôm qua tôi đã thêm mapping MapStruct cho DTO lồng nhau.', 'Hôm nay tôi đang review implementation được sinh ra.', 'Build đang bị chặn vì một build agent đang offline.'], [['nested DTO', 'DTO chứa object con'], ['generated implementation', 'phần triển khai được tự sinh'], ['build agent', 'máy hoặc tiến trình chạy build']]],
  ['Hôm qua bạn thêm retry cho lời gọi tới dịch vụ thanh toán. Hôm nay bạn kiểm tra timeout và idempotency. Bạn cần QA cung cấp sandbox account.', 'I added retry handling for calls to the payment service.', 'Today, I’m checking the timeout and idempotency behavior.', 'I need a sandbox account from QA to verify the payment flow.', ['Hôm qua tôi đã thêm xử lý retry cho lời gọi dịch vụ thanh toán.', 'Hôm nay tôi đang kiểm tra timeout và hành vi idempotency.', 'Tôi cần tài khoản sandbox từ QA để xác minh luồng thanh toán.'], [['retry handling', 'xử lý thử lại khi lỗi tạm thời'], ['idempotency', 'tính chất gọi lặp nhưng không tạo tác động trùng'], ['sandbox account', 'tài khoản môi trường thử nghiệm']]],
  ['Hôm qua bạn cùng frontend thống nhất response DTO cho màn hình admin. Hôm nay bạn cập nhật OpenAPI document. Chưa có blocker.', 'I aligned the response DTO with the frontend team.', 'Today, I’m updating the OpenAPI documentation.', 'There are no blockers. The endpoint contract is agreed with the team.', ['Tôi đã thống nhất response DTO với nhóm frontend.', 'Hôm nay tôi đang cập nhật tài liệu OpenAPI.', 'Không có vướng mắc. Contract của endpoint đã được nhóm thống nhất.'], [['align with', 'thống nhất với'], ['endpoint contract', 'quy ước request/response của endpoint'], ['documentation', 'tài liệu hướng dẫn']]],
  ['Hôm qua bạn điều tra lỗi kết nối DB sau deploy. Hôm nay bạn kiểm tra pool config với DevOps. Bạn đang chờ quyền xem log production.', 'I investigated the database connection errors after deployment.', 'Today, I’m reviewing the pool configuration with DevOps.', 'I’m waiting for production log access to confirm the pattern.', ['Tôi đã điều tra lỗi kết nối database sau deploy.', 'Hôm nay tôi đang review cấu hình pool cùng DevOps.', 'Tôi đang chờ quyền xem log production để xác nhận hiện tượng.'], [['connection error', 'lỗi kết nối'], ['pool configuration', 'cấu hình nhóm kết nối'], ['confirm the pattern', 'xác nhận quy luật xảy ra']]],
  ['Hôm qua bạn thêm audit log khi admin đổi role. Hôm nay bạn viết test kiểm tra actor và timestamp. Product chưa trả lời về thời gian lưu log.', 'I added an audit log for admin role changes.', 'Today, I’m testing the actor and timestamp fields.', 'I’m waiting for Product to confirm the audit log retention period.', ['Tôi đã thêm audit log cho thao tác admin đổi role.', 'Hôm nay tôi đang kiểm tra field người thực hiện và thời gian.', 'Tôi đang chờ Product xác nhận thời gian lưu audit log.'], [['audit log', 'nhật ký ghi lại hành động quan trọng'], ['actor', 'người thực hiện hành động'], ['retention period', 'thời gian lưu trữ']]],
  ['Hôm qua bạn sửa conflict trong migration SQL. Hôm nay bạn chạy migration trên staging rồi smoke test. DevOps đang cập nhật database snapshot.', 'I resolved a conflict in the SQL migration.', 'Today, I’ll run it in staging and perform a smoke test.', 'I’m waiting for DevOps to finish the database snapshot.', ['Tôi đã xử lý conflict trong migration SQL.', 'Hôm nay tôi sẽ chạy trên staging và thực hiện smoke test.', 'Tôi đang chờ DevOps hoàn tất database snapshot.'], [['migration conflict', 'xung đột giữa các thay đổi schema'], ['smoke test', 'kiểm tra nhanh luồng chính'], ['database snapshot', 'bản chụp trạng thái database']]],
  ['Hôm qua bạn giảm payload của endpoint user bằng projection DTO. Hôm nay bạn đo response time ở dữ liệu lớn. Không có blocker.', 'I reduced the user endpoint payload with a projection DTO.', 'Today, I’m measuring response time with a larger dataset.', 'I don’t have any blockers. I’ll compare the results with the baseline.', ['Tôi đã giảm payload của endpoint user bằng projection DTO.', 'Hôm nay tôi đang đo thời gian phản hồi với tập dữ liệu lớn hơn.', 'Tôi không có vướng mắc. Tôi sẽ so sánh kết quả với số liệu ban đầu.'], [['payload', 'dữ liệu được truyền trong request hoặc response'], ['dataset', 'tập dữ liệu'], ['baseline', 'số liệu ban đầu để so sánh']]],
  ['Hôm qua bạn review PR và yêu cầu thêm transaction cho thao tác hoàn tiền. Hôm nay bạn kiểm tra cách rollback khi ghi audit log lỗi. Tác giả PR chưa phản hồi.', 'I reviewed a pull request and suggested a transaction for the refund flow.', 'Today, I’m checking rollback behavior if audit logging fails.', 'I’m waiting for the author to respond to the review comments.', ['Tôi đã review pull request và đề xuất transaction cho luồng hoàn tiền.', 'Hôm nay tôi đang kiểm tra rollback nếu ghi audit log thất bại.', 'Tôi đang chờ tác giả phản hồi các nhận xét review.'], [['refund flow', 'luồng hoàn tiền'], ['rollback behavior', 'hành vi hoàn tác thay đổi'], ['review comment', 'nhận xét trong code review']]],
  ['Hôm qua bạn khắc phục lỗi cấu hình CORS trên staging. Hôm nay bạn xác nhận domain production với khách hàng. Chưa có blocker kỹ thuật.', 'I fixed the CORS configuration in staging.', 'Today, I’m confirming the production domain with the client.', 'There are no technical blockers. I’m waiting for the client’s domain confirmation.', ['Tôi đã sửa cấu hình CORS trên staging.', 'Hôm nay tôi đang xác nhận domain production với khách hàng.', 'Không có vướng mắc kỹ thuật. Tôi đang chờ khách xác nhận domain.'], [['CORS configuration', 'cấu hình quyền gọi API khác domain'], ['production domain', 'tên miền môi trường chạy thật'], ['technical blocker', 'vướng mắc kỹ thuật']]],
  ['Hôm qua bạn thêm health check cho dịch vụ. Hôm nay bạn tích hợp nó vào deployment pipeline. Nhóm platform chưa xác nhận path health endpoint.', 'I added a health check endpoint to the service.', 'Today, I’m wiring it into the deployment pipeline.', 'I need the platform team to confirm the health check path.', ['Tôi đã thêm health check endpoint cho dịch vụ.', 'Hôm nay tôi đang nối endpoint đó vào deployment pipeline.', 'Tôi cần nhóm platform xác nhận đường dẫn health check.'], [['health check endpoint', 'endpoint kiểm tra trạng thái dịch vụ'], ['wire into', 'kết nối vào quy trình'], ['path', 'đường dẫn URL']]],
];

const clarify = [
  ['Khách nói: “Add search to the customer page.” Chưa rõ trường tìm kiếm và cách khớp.', ['Which fields should users be able to search by?', 'Should the search use an exact match or partial text?', 'Should the search apply across all customer records or only the current page?'], 'Search by name, email, or phone using partial matches across all records. Results should be paginated.', 'Tìm theo tên, email hoặc số điện thoại bằng cách khớp một phần trên toàn bộ dữ liệu. Kết quả cần phân trang.', 'Tóm tắt trường tìm kiếm, kiểu khớp và việc phân trang; xác nhận thêm giới hạn quyền xem customer.', 'I’ll support partial search by name, email, and phone across all records, with pagination. Are there any role restrictions for viewing customers?', [['partial match', 'khớp một phần chuỗi'], ['across all records', 'trên toàn bộ bản ghi'], ['role restriction', 'giới hạn theo vai trò']]],
  ['Khách nói: “Users can update their profile.” Chưa rõ trường nào được sửa và email có cần xác minh lại không.', ['Which profile fields can a user edit?', 'Should users verify their email after changing it?', 'Should profile changes take effect immediately or require approval?'], 'Users can edit their name and phone immediately. Email changes require verification. Role and account status are read-only.', 'User được sửa tên và số điện thoại ngay. Đổi email cần xác minh. Role và trạng thái tài khoản chỉ đọc.', 'Ghi rõ field được sửa, field cần xác minh và field chỉ đọc; xác nhận email cũ còn dùng được trong lúc chờ xác minh.', 'Users can update their name and phone immediately. Email changes require verification, while role and status remain read-only. Can users keep signing in with the old email until verification is complete?', [['read-only', 'chỉ đọc, không chỉnh sửa được'], ['email verification', 'xác minh địa chỉ email'], ['take effect', 'bắt đầu có hiệu lực']]],
  ['Khách yêu cầu: “Send a reminder before a subscription expires.” Chưa rõ thời điểm, tần suất và người nhận.', ['How many days before expiration should we send the reminder?', 'Should we send one reminder or repeat it?', 'Should the reminder go to the account owner or every team member?'], 'Send one email seven days before expiration to the account owner. Do not send it if the subscription has already been renewed.', 'Gửi một email trước ngày hết hạn bảy ngày cho chủ tài khoản. Không gửi nếu subscription đã được gia hạn.', 'Xác nhận thời điểm, số lần, người nhận và điều kiện bỏ qua email khi đã gia hạn.', 'I’ll send one reminder to the account owner seven days before expiration, unless the subscription has already been renewed. Is email the only channel you need?', [['expiration', 'thời điểm hết hạn'], ['account owner', 'chủ tài khoản'], ['renew', 'gia hạn']]],
  ['Khách muốn: “Allow managers to approve expenses.” Chưa rõ hạn mức và trường hợp manager tự gửi yêu cầu.', ['Are there different approval limits by expense amount?', 'Can a manager approve their own expense?', 'What should happen when a request is rejected?'], 'A manager can approve up to $1,000 but cannot approve their own request. Rejected requests must include a reason and return to the employee.', 'Manager có thể duyệt đến 1.000 đô nhưng không được tự duyệt yêu cầu của mình. Yêu cầu bị từ chối phải có lý do và trả lại nhân viên.', 'Ghi rõ hạn mức, ngăn tự duyệt và yêu cầu lý do khi từ chối; hỏi thêm ai duyệt khoản vượt hạn mức.', 'Managers can approve up to $1,000 and cannot approve their own expenses. Rejections need a reason. Who should approve requests above that limit?', [['approval limit', 'hạn mức phê duyệt'], ['approve their own request', 'tự phê duyệt yêu cầu của mình'], ['rejection reason', 'lý do từ chối']]],
  ['Khách nói: “Import users from a spreadsheet.” Chưa rõ định dạng, xử lý dữ liệu sai và trùng email.', ['Which spreadsheet formats and columns should be supported?', 'Should the import stop at the first invalid row or report all errors?', 'How should duplicate email addresses be handled?'], 'Support CSV with a template. Validate all rows, return a downloadable error report, and skip users whose email already exists.', 'Hỗ trợ CSV theo mẫu. Kiểm tra toàn bộ dòng, trả file báo lỗi để tải xuống và bỏ qua user có email đã tồn tại.', 'Xác nhận format và xử lý lỗi theo từng dòng; làm rõ file lỗi có chứa dữ liệu nhạy cảm nào không.', 'I’ll use the CSV template, validate every row, and skip existing emails. The user will receive an error report for invalid rows. Should that report include the original row values?', [['invalid row', 'dòng dữ liệu không hợp lệ'], ['downloadable error report', 'báo cáo lỗi có thể tải xuống'], ['duplicate email', 'email bị trùng']]],
  ['Khách muốn: “Add a dashboard for sales.” Chưa rõ chỉ số, khoảng thời gian và múi giờ.', ['Which sales metrics should appear on the dashboard?', 'What date range and default period should be shown?', 'Which timezone should be used for daily totals?'], 'Show revenue, order count, and average order value. Default to the current month and use the business timezone configured for each region.', 'Hiển thị doanh thu, số đơn và giá trị đơn trung bình. Mặc định tháng hiện tại và dùng múi giờ nghiệp vụ đã cấu hình cho từng khu vực.', 'Chốt ba chỉ số, khoảng mặc định và múi giờ; xác nhận vai trò nào được xem số liệu doanh thu.', 'The dashboard will show revenue, order count, and average order value for the current month, using each region’s business timezone. Which roles should have access to the revenue data?', [['average order value', 'giá trị đơn hàng trung bình'], ['date range', 'khoảng thời gian'], ['business timezone', 'múi giờ nghiệp vụ']]],
  ['Khách nói: “Let users upload documents.” Chưa rõ loại file, dung lượng và quyền xem.', ['Which file types and maximum file size should we allow?', 'Who can view or download an uploaded document?', 'Should uploaded files be scanned before they become available?'], 'Allow PDF and PNG files up to 10 MB. The uploader and assigned case workers can access them. Files must pass malware scanning first.', 'Cho phép file PDF và PNG tối đa 10 MB. Người tải lên và nhân viên được giao hồ sơ có thể truy cập. File phải qua quét mã độc trước.', 'Chốt định dạng, dung lượng, quyền truy cập và bước quét; hỏi thời hạn lưu file.', 'I’ll allow PDF and PNG files up to 10 MB, restrict access to the uploader and assigned case workers, and scan each file before release. How long should we retain the documents?', [['maximum file size', 'dung lượng file tối đa'], ['assigned case worker', 'nhân viên được giao xử lý hồ sơ'], ['retain a document', 'lưu giữ tài liệu']]],
  ['Khách yêu cầu: “Add an API rate limit.” Chưa rõ giới hạn theo user, token hay IP và response khi vượt hạn.', ['Should the limit be applied per user, API key, or IP address?', 'What request limit and time window should we use?', 'What response should clients receive when the limit is exceeded?'], 'Limit each API key to 100 requests per minute. Return HTTP 429 with a Retry-After header.', 'Giới hạn mỗi API key ở 100 request mỗi phút. Trả HTTP 429 kèm header Retry-After.', 'Ghi rõ key, số request, cửa sổ thời gian và response; hỏi có endpoint nào cần hạn mức riêng không.', 'I’ll limit each API key to 100 requests per minute and return 429 with Retry-After. Do any endpoints need a separate limit?', [['rate limit', 'giới hạn tần suất request'], ['time window', 'cửa sổ thời gian áp dụng'], ['exceeded', 'vượt quá']]],
  ['Khách nói: “Keep an audit history for changes.” Chưa rõ thao tác nào, lưu trường cũ/mới và ai được xem.', ['Which actions and fields must be included in the audit history?', 'Should we record both the previous and new values?', 'Which roles can view the audit history?'], 'Record changes to role, status, and permissions with the actor and timestamp. Only admins and auditors can view it.', 'Ghi lại thay đổi role, trạng thái và permission kèm người thực hiện và thời gian. Chỉ admin và auditor được xem.', 'Liệt kê field và metadata cần lưu; xác nhận quy định lưu giữ và cách che dữ liệu nhạy cảm.', 'I’ll record role, status, and permission changes with the actor and timestamp, visible only to admins and auditors. How long should these records be retained, and should any values be masked?', [['previous value', 'giá trị trước khi thay đổi'], ['actor', 'người thực hiện'], ['mask a value', 'che một phần giá trị']]],
  ['Khách muốn: “Make the service available in multiple languages.” Chưa rõ ngôn ngữ, phần cần dịch và ngôn ngữ mặc định.', ['Which languages should be available in the first release?', 'Should user-generated content be translated or only interface labels?', 'How should we choose the default language for a new user?'], 'Start with English and Vietnamese. Translate interface labels only. Use the user’s saved preference, then fall back to English.', 'Bản đầu hỗ trợ tiếng Anh và tiếng Việt. Chỉ dịch nhãn giao diện. Dùng lựa chọn đã lưu của user, nếu chưa có thì mặc định tiếng Anh.', 'Chốt phạm vi dịch và quy tắc chọn ngôn ngữ; hỏi ai cung cấp nội dung dịch và duyệt bản dịch.', 'The first release will support English and Vietnamese for interface labels. We’ll use the saved preference and fall back to English. Who will provide and review the translations?', [['user-generated content', 'nội dung do người dùng tạo'], ['saved preference', 'lựa chọn đã lưu'], ['fall back to', 'dùng phương án dự phòng']]],
  ['Khách yêu cầu: “Send a webhook when an order changes.” Chưa rõ event, retry và xác thực.', ['Which order events should trigger a webhook?', 'How many times should we retry a failed delivery?', 'How should the receiving system verify that a webhook is authentic?'], 'Send webhooks for paid, cancelled, and shipped events. Retry with backoff for up to 24 hours and sign each payload with a shared secret.', 'Gửi webhook khi đơn được thanh toán, hủy hoặc giao. Retry theo backoff tối đa 24 giờ và ký từng payload bằng shared secret.', 'Xác nhận event, chính sách retry và chữ ký; hỏi cách khách muốn quản lý endpoint và secret.', 'I’ll send webhooks for paid, cancelled, and shipped events, retry with backoff for 24 hours, and sign each payload. How should clients rotate their webhook secret?', [['webhook delivery', 'việc gửi webhook'], ['retry with backoff', 'thử lại với khoảng chờ tăng dần'], ['sign a payload', 'ký payload để xác minh nguồn gửi']]],
  ['Khách nói: “Archive old records.” Chưa rõ định nghĩa cũ, có thể khôi phục không và ai được xem.', ['How old must a record be before it is archived?', 'Should archived records be searchable or restorable?', 'Are there legal or retention rules we need to follow?'], 'Archive records after two years without activity. Admins can restore them, and archived data must remain available for seven years.', 'Lưu trữ hồ sơ sau hai năm không hoạt động. Admin có thể khôi phục, dữ liệu lưu trữ phải còn sẵn trong bảy năm.', 'Chốt ngưỡng, khả năng khôi phục và thời hạn lưu; hỏi việc archive ảnh hưởng báo cáo hiện tại thế nào.', 'I’ll archive records after two years of inactivity, allow admins to restore them, and retain them for seven years. Should archived records be excluded from the default reports?', [['archive a record', 'đưa bản ghi vào lưu trữ'], ['restore', 'khôi phục'], ['retention rule', 'quy tắc thời hạn lưu trữ']]],
  ['Khách muốn: “Let users cancel an order.” Chưa rõ thời điểm, hoàn tiền và đơn đã đóng gói.', ['Until which order status can a customer cancel?', 'Should cancellation trigger an automatic refund?', 'What should happen if the order has already been packed or shipped?'], 'Customers can cancel before shipment. Paid orders should be refunded automatically, while shipped orders require contacting support.', 'Khách có thể hủy trước khi giao. Đơn đã thanh toán cần được hoàn tiền tự động, còn đơn đã gửi phải liên hệ hỗ trợ.', 'Ghi rõ ngưỡng trạng thái và cách hoàn tiền; xác nhận quy trình cho đơn đang đóng gói.', 'Customers can cancel before shipment, and paid orders are refunded automatically. What should happen to an order that is already being packed?', [['order status', 'trạng thái đơn hàng'], ['automatic refund', 'hoàn tiền tự động'], ['being packed', 'đang được đóng gói']]],
  ['Khách nói: “Notify the team when a deployment fails.” Chưa rõ môi trường, kênh và nội dung thông báo.', ['Which environments should trigger a notification?', 'Which channel and team should receive the alert?', 'What deployment details should the alert include?'], 'Notify the on-call channel for staging and production failures. Include the service, release version, environment, and link to the build log.', 'Thông báo vào kênh trực on-call khi staging hoặc production lỗi. Bao gồm service, phiên bản, môi trường và link build log.', 'Xác nhận môi trường, kênh và thông tin cần đính kèm; hỏi có cần phân cấp mức độ giữa staging và production không.', 'I’ll notify the on-call channel for staging and production failures with the release details and build log. Should production alerts use a higher severity than staging alerts?', [['on-call channel', 'kênh của nhóm trực xử lý sự cố'], ['release version', 'phiên bản phát hành'], ['severity', 'mức độ nghiêm trọng']]],
  ['Khách muốn: “Add bulk status updates.” Chưa rõ số lượng tối đa, hành vi khi một bản ghi lỗi và quyền người dùng.', ['What is the maximum number of records per bulk request?', 'Should valid records still be updated if some records fail?', 'Which roles can perform this operation?'], 'Allow up to 500 records. Process valid records and return a result for each failed record. Only operations managers can use it.', 'Cho phép tối đa 500 bản ghi. Xử lý bản ghi hợp lệ và trả kết quả cho từng bản ghi lỗi. Chỉ quản lý vận hành được dùng.', 'Chốt số lượng tối đa, xử lý lỗi từng dòng và role; hỏi có cần lưu audit log cho thao tác hàng loạt không.', 'I’ll process up to 500 records, report each failure, and restrict the action to operations managers. Should we create an audit entry for every record changed?', [['bulk request', 'request xử lý hàng loạt'], ['per-record result', 'kết quả theo từng bản ghi'], ['audit entry', 'bản ghi nhật ký kiểm toán']]],
  ['Khách yêu cầu: “Support login with an identity provider.” Chưa rõ nhà cung cấp, luồng đăng nhập và user mapping.', ['Which identity provider and protocol should we support?', 'Should existing accounts be linked by verified email?', 'What should happen when a user is removed from the identity provider?'], 'Use Microsoft Entra ID with OpenID Connect. Link accounts by verified email. Disable access when the identity provider reports that a user is inactive.', 'Dùng Microsoft Entra ID với OpenID Connect. Liên kết tài khoản theo email đã xác minh. Tắt quyền truy cập khi identity provider báo user không hoạt động.', 'Chốt provider, protocol, quy tắc liên kết và đồng bộ trạng thái; xác nhận xử lý tài khoản trùng email.', 'We’ll use Microsoft Entra ID with OpenID Connect and link verified emails. If a local account already uses that email, should we require an admin to approve the link?', [['identity provider', 'nhà cung cấp xác thực danh tính'], ['verified email', 'email đã xác minh'], ['link accounts', 'liên kết các tài khoản']]],
  ['Khách muốn: “Improve the report export.” Chưa rõ định dạng, dữ liệu lớn và xử lý tiến trình lâu.', ['Which export formats and fields are required?', 'How many rows should a typical export contain?', 'Should large exports run in the background with a download link?'], 'Provide CSV and Excel. Exports can contain up to 200,000 rows, so large jobs should run asynchronously and notify the requester when ready.', 'Cung cấp CSV và Excel. File có thể lên đến 200.000 dòng nên job lớn cần chạy bất đồng bộ và báo người yêu cầu khi hoàn tất.', 'Xác nhận format, kích thước dữ liệu và xử lý async; hỏi link tải tồn tại trong bao lâu.', 'I’ll provide CSV and Excel exports, run large jobs asynchronously, and notify the requester when they are ready. How long should the download link remain valid?', [['run in the background', 'chạy nền'], ['asynchronously', 'bất đồng bộ'], ['download link', 'đường dẫn tải file']]],
];

const incidents = [
  ['Ticket: “The service returns 401 for valid users.” Logs show token issuer mismatch after a new auth configuration was deployed.', 'Compare the expected issuer with the token issuer in a failing request.', 'Check whether all application instances received the same auth configuration.', 'Disable issuer validation so all tokens are accepted.', 'The logs show an issuer mismatch after the configuration change. I suspect the service and identity provider use different issuer values. I’d compare the token claims and deployed configuration, then verify the fix with a test token.', 'Log cho thấy issuer không khớp sau thay đổi cấu hình. Tôi nghi service và identity provider đang dùng giá trị issuer khác nhau. Tôi sẽ so sánh claim trong token với cấu hình đã deploy, rồi xác minh bằng test token.', [['issuer mismatch', 'issuer không khớp'], ['token claim', 'claim/thông tin trong token'], ['deployed configuration', 'cấu hình đã được triển khai']]],
  ['Ticket: “The API returns duplicate orders.” Logs show client retries after a timeout, and the create endpoint has no idempotency key.', 'Check whether the client retries the same request after a timeout.', 'Review whether the create operation supports an idempotency key.', 'Remove the timeout so clients cannot retry.', 'The logs show retries after a timeout, and the create endpoint has no idempotency key. I suspect the same request is being processed more than once. I’d check request IDs and add idempotent handling before changing the timeout.', 'Log cho thấy client retry sau timeout và endpoint tạo đơn chưa có idempotency key. Tôi nghi cùng một request bị xử lý nhiều lần. Tôi sẽ kiểm tra request ID và thêm xử lý idempotent trước khi đổi timeout.', [['idempotency key', 'khóa giúp nhận diện request lặp'], ['process more than once', 'xử lý nhiều hơn một lần'], ['request ID', 'mã định danh request']]],
  ['Ticket: “Users see old profile data after saving.” Cache metrics show a high hit rate and the profile cache is not invalidated on update.', 'Check the cache key and invalidation behavior after a profile update.', 'Compare the database value with the cached response for the same user.', 'Disable authentication to refresh the profile.', 'The cache is returning a high number of hits, and the update flow does not invalidate the profile entry. I suspect users receive a stale cached response. I’d compare the database and cache values, then invalidate or refresh the correct cache key after updates.', 'Cache có tỷ lệ hit cao và luồng cập nhật không xóa entry profile. Tôi nghi người dùng nhận response cache cũ. Tôi sẽ so sánh dữ liệu DB với cache rồi xóa hoặc cập nhật đúng cache key sau khi lưu.', [['cache invalidation', 'xóa cache khi dữ liệu nguồn thay đổi'], ['stale response', 'response chứa dữ liệu cũ'], ['cache key', 'khóa dùng để tìm dữ liệu trong cache']]],
  ['Ticket: “The service cannot connect to Redis.” Logs show connection refused after a container restart; Redis health check is still failing.', 'Check the Redis container health and service name used by the application.', 'Compare the Redis port and network settings after restart.', 'Increase the API request timeout and ignore the Redis error.', 'The connection is refused and the Redis health check is failing after restart. I suspect Redis is not ready or the service is using an incorrect host or port. I’d inspect container health, network configuration, and startup order before changing API timeouts.', 'Kết nối bị từ chối và health check Redis lỗi sau khi restart. Tôi nghi Redis chưa sẵn sàng hoặc service dùng sai host/port. Tôi sẽ kiểm tra tình trạng container, network và thứ tự khởi động trước khi đổi timeout API.', [['connection refused', 'kết nối bị từ chối'], ['startup order', 'thứ tự khởi động dịch vụ'], ['container health', 'tình trạng hoạt động của container']]],
  ['Ticket: “The deployment is healthy, but users get 502.” Reverse proxy logs show upstream connection reset during startup.', 'Check application readiness and startup duration behind the proxy.', 'Compare proxy timeout and upstream settings with the application startup behavior.', 'Restart all production services repeatedly until it works.', 'The proxy logs show the upstream connection resets during startup. I suspect traffic reaches the application before it is ready. I’d verify readiness checks and startup time, then review the proxy upstream configuration and deployment sequence.', 'Log proxy cho thấy kết nối tới upstream bị reset lúc khởi động. Tôi nghi traffic đến ứng dụng trước khi nó sẵn sàng. Tôi sẽ xác minh readiness check và thời gian startup, rồi xem cấu hình upstream và thứ tự deploy.', [['upstream', 'dịch vụ phía sau proxy nhận request'], ['readiness check', 'kiểm tra ứng dụng đã sẵn sàng nhận traffic'], ['connection reset', 'kết nối bị đóng đột ngột']]],
  ['Ticket: “Search results are missing recent orders.” The search index timestamp is behind the database, and the indexing queue has grown.', 'Check the indexing queue lag and failed indexing messages.', 'Compare the database record with its search index document.', 'Increase the database connection pool without checking the indexer.', 'The search index is behind the database and the indexing queue is growing. I suspect the indexer is delayed or failing on some messages. I’d inspect queue lag, retries, and failed events, then compare an affected record with its indexed document.', 'Search index chậm hơn database và hàng đợi indexing đang tăng. Tôi nghi indexer bị trễ hoặc lỗi với một số message. Tôi sẽ kiểm tra queue lag, retry và event lỗi, rồi so sánh bản ghi bị ảnh hưởng với document trong index.', [['indexing queue', 'hàng đợi cập nhật search index'], ['queue lag', 'độ trễ của hàng đợi'], ['indexed document', 'document đã được ghi vào search index']]],
  ['Ticket: “Email notifications are sent twice.” Queue metrics show the consumer restarted before acknowledging a processed message.', 'Check the consumer acknowledgement flow and retry policy.', 'Review whether notification processing is idempotent.', 'Delete all queued messages immediately.', 'The consumer restarted before acknowledging a message, so the queue may have delivered it again. I suspect the notification handler is not idempotent. I’d review acknowledgement timing, retry behavior, and duplicate detection before changing the queue.', 'Consumer restart trước khi xác nhận message có thể khiến queue gửi lại. Tôi nghi handler thông báo chưa idempotent. Tôi sẽ xem thời điểm ack, retry và cách phát hiện trùng trước khi thay đổi queue.', [['acknowledge a message', 'xác nhận đã xử lý message'], ['consumer', 'tiến trình nhận và xử lý message'], ['duplicate detection', 'phát hiện bản ghi hoặc sự kiện trùng']]],
  ['Ticket: “Payments fail for some customers.” Logs show 429 responses from the payment provider during a traffic spike.', 'Check provider rate limits and the timing of outbound requests.', 'Review retry delays and whether the retry policy respects Retry-After.', 'Retry every failed request immediately in a tight loop.', 'The payment provider returns 429 during the traffic spike. I suspect we are exceeding its rate limit. I’d review request volume, concurrency, and Retry-After handling, then use bounded backoff so retries do not increase the load.', 'Nhà cung cấp thanh toán trả 429 lúc traffic tăng. Tôi nghi hệ thống vượt rate limit. Tôi sẽ xem số request, concurrency và cách xử lý Retry-After, sau đó dùng backoff có giới hạn để retry không làm tải tăng thêm.', [['rate limit', 'giới hạn tần suất request'], ['bounded backoff', 'thời gian chờ tăng dần nhưng có giới hạn'], ['outbound request', 'request gửi tới dịch vụ ngoài']]],
  ['Ticket: “The API is returning 403 for users who should have access.” Recent role mapping changed from ADMIN to ROLE_ADMIN.', 'Inspect the granted authorities in the security context.', 'Compare the role stored in the database with the role expected by the authorization rule.', 'Remove the authorization rule from the endpoint.', 'The role mapping changed recently, and the endpoint returns 403. I suspect the granted authority no longer matches the access rule. I’d inspect the security context and compare the stored role, token claims, and required authority.', 'Mapping role vừa thay đổi và endpoint trả 403. Tôi nghi granted authority không còn khớp access rule. Tôi sẽ kiểm tra security context và so sánh role trong DB, claim token và authority endpoint yêu cầu.', [['granted authority', 'quyền đã được cấp cho principal'], ['security context', 'ngữ cảnh xác thực và quyền hiện tại'], ['access rule', 'quy tắc kiểm tra quyền truy cập']]],
  ['Ticket: “A report total is different from the sum of its rows.” The report query joins payments and items, and some orders have multiple payments.', 'Check whether the joins multiply rows before aggregation.', 'Compare the report query with a smaller dataset where expected totals are known.', 'Round every amount to an integer before summing.', 'The report joins payments and items, and some orders have multiple payments. I suspect the join creates duplicate rows before aggregation. I’d inspect the query cardinality and verify totals against a small known dataset before changing the calculation.', 'Report join payments với items, trong khi có đơn có nhiều lần thanh toán. Tôi nghi phép join nhân bản dòng trước khi tổng hợp. Tôi sẽ kiểm tra số lượng dòng và đối chiếu tổng với tập dữ liệu nhỏ đã biết trước khi đổi phép tính.', [['aggregation', 'phép tổng hợp dữ liệu'], ['cardinality', 'số lượng dòng phát sinh từ phép join'], ['known dataset', 'tập dữ liệu có kết quả dự kiến rõ ràng']]],
  ['Ticket: “The app crashes after processing a large CSV.” Logs show heap usage rises until OutOfMemoryError.', 'Check whether the import reads the whole file into memory.', 'Review batch size and whether processed records are released.', 'Increase the maximum upload size to prevent partial processing.', 'Heap usage grows until an OutOfMemoryError during the CSV import. I suspect the file or all parsed rows are held in memory. I’d inspect the import strategy, use streaming or bounded batches, and monitor memory with a representative file.', 'Heap tăng đến OutOfMemoryError khi import CSV. Tôi nghi file hoặc toàn bộ dòng parse đang bị giữ trong bộ nhớ. Tôi sẽ xem cách import, dùng streaming hoặc batch có giới hạn và theo dõi memory với file đại diện.', [['heap usage', 'mức sử dụng vùng nhớ heap'], ['streaming', 'xử lý dữ liệu theo luồng thay vì tải toàn bộ'], ['bounded batch', 'lô xử lý có kích thước giới hạn']]],
  ['Ticket: “Some API requests take much longer than usual.” Traces show time spent waiting for a third-party address service.', 'Compare external call latency with the total API response time.', 'Check timeout, circuit breaker, and fallback behavior for the dependency.', 'Increase every server thread count without measuring saturation.', 'The traces show most of the request time is spent waiting for the address service. I suspect its latency is affecting our API. I’d check timeout and circuit breaker settings, measure the dependency latency, and confirm the fallback behavior.', 'Trace cho thấy phần lớn thời gian request là chờ dịch vụ địa chỉ. Tôi nghi latency của dịch vụ này ảnh hưởng API. Tôi sẽ xem timeout, circuit breaker, đo latency dependency và xác nhận fallback.', [['trace', 'dấu vết thời gian qua các bước xử lý request'], ['circuit breaker', 'cơ chế ngắt gọi dependency đang lỗi'], ['fallback', 'phương án thay thế khi dependency lỗi']]],
  ['Ticket: “The database has too many idle connections.” Metrics show connection count increases after each scheduled job run.', 'Check whether each job closes its database resources and transaction scope.', 'Compare connection counts before and after a job completes.', 'Restart the database after every scheduled job.', 'Connections increase after each scheduled job run. I suspect a resource or transaction is not being released. I’d compare connection counts around the job lifecycle and review cleanup paths before restarting services.', 'Số connection tăng sau mỗi lần scheduled job chạy. Tôi nghi resource hoặc transaction chưa được giải phóng. Tôi sẽ so sánh connection trước/sau vòng đời job và xem các nhánh cleanup trước khi restart dịch vụ.', [['idle connection', 'kết nối đang rảnh'], ['release a resource', 'giải phóng tài nguyên'], ['cleanup path', 'nhánh xử lý giải phóng tài nguyên']]],
  ['Ticket: “The service started returning 500 after a database migration.” Logs show a missing column in the new application version.', 'Compare the deployed application version with the schema migration status.', 'Check whether every environment ran the migration successfully.', 'Remove the new field from the API response without checking the code path.', 'The application reports a missing column after the migration release. I suspect the schema and application versions are out of sync. I’d check migration status in the affected environment and verify the deployment order and compatibility assumptions.', 'Ứng dụng báo thiếu cột sau khi phát hành migration. Tôi nghi schema và phiên bản ứng dụng không đồng bộ. Tôi sẽ kiểm tra trạng thái migration của môi trường bị ảnh hưởng và xác minh thứ tự deploy, giả định tương thích.', [['out of sync', 'không đồng bộ'], ['migration status', 'trạng thái thực thi migration'], ['deployment order', 'thứ tự triển khai']]],
  ['Ticket: “Requests fail only on one application instance.” Load balancer health checks pass, but that instance has a different environment variable value.', 'Compare environment variables and secret versions across instances.', 'Route a request to the affected instance and compare its configuration.', 'Restart the whole database cluster.', 'Only one instance fails, and its environment variable differs from the others. I suspect configuration drift. I’d compare the instance settings, confirm the intended secret version, and check why the deployment produced inconsistent configuration.', 'Chỉ một instance lỗi và biến môi trường khác các instance còn lại. Tôi nghi cấu hình bị lệch. Tôi sẽ so sánh setting, xác nhận secret version đúng và tìm lý do deployment tạo cấu hình không đồng nhất.', [['configuration drift', 'cấu hình các instance bị lệch nhau'], ['secret version', 'phiên bản secret'], ['load balancer', 'bộ phân phối request']]],
  ['Ticket: “The API returns an empty list for a valid date range.” Server logs use UTC, but the client sends local dates without a timezone.', 'Compare the parsed request dates with the stored timestamps and timezone.', 'Check the boundary conditions at the start and end of the requested range.', 'Change all stored timestamps to local time immediately.', 'The client sends local dates while the server and database use UTC. I suspect a timezone or range-boundary mismatch. I’d inspect the parsed timestamps and compare the exact start and end conditions with records near midnight.', 'Client gửi ngày địa phương trong khi server và DB dùng UTC. Tôi nghi lệch múi giờ hoặc ranh giới khoảng ngày. Tôi sẽ kiểm tra timestamp sau parse và điều kiện đầu/cuối với bản ghi gần nửa đêm.', [['timezone mismatch', 'lệch múi giờ'], ['range boundary', 'ranh giới đầu/cuối khoảng dữ liệu'], ['parsed timestamp', 'timestamp sau khi chuyển đổi từ request']]],
  ['Ticket: “Health checks pass but the service cannot process messages.” Consumer logs show repeated deserialization errors for a new event field.', 'Inspect the event schema and compatibility with the deployed consumer version.', 'Check the dead-letter queue and identify the failing message payload.', 'Delete the new event field from every producer without checking compatibility.', 'The consumer repeatedly fails to deserialize an event after a schema change. I suspect the producer and consumer versions are incompatible. I’d inspect the payload, schema compatibility, and dead-letter queue before deciding on a safe rollout.', 'Consumer liên tục lỗi deserialize event sau thay đổi schema. Tôi nghi phiên bản producer và consumer không tương thích. Tôi sẽ kiểm tra payload, khả năng tương thích schema và dead-letter queue trước khi chọn cách rollout an toàn.', [['deserialize', 'chuyển dữ liệu nhận được thành object'], ['schema compatibility', 'khả năng tương thích giữa các phiên bản schema'], ['dead-letter queue', 'hàng đợi chứa message xử lý thất bại']]],
];

const answerBuilder = [
  ['How do you explain a technical decision to a non-technical stakeholder?', 'Bạn giải thích quyết định kỹ thuật với người không chuyên như thế nào?', ['The team needed to replace a manual approval process that often delayed customer requests.', 'I explained the current bottleneck using examples and agreed on the business outcome before discussing implementation.', 'I proposed a staged workflow with clear permissions and an audit trail.', 'The stakeholder approved the approach because the risks and expected impact were easy to understand.'], ['Nhóm cần thay quy trình duyệt thủ công thường làm chậm yêu cầu của khách.', 'Tôi dùng ví dụ giải thích điểm nghẽn và thống nhất kết quả nghiệp vụ trước khi bàn cách triển khai.', 'Tôi đề xuất workflow theo từng bước với quyền rõ ràng và audit trail.', 'Người liên quan đồng ý vì rủi ro và tác động dự kiến đã được trình bày dễ hiểu.'], [['business outcome', 'kết quả nghiệp vụ cần đạt'], ['staged workflow', 'quy trình theo từng bước'], ['audit trail', 'dấu vết ghi lại lịch sử thao tác']]],
  ['Tell me about a time you reduced repeated code.', 'Kể về lần bạn giảm code lặp lại.', ['Several controllers repeated the same validation and error response logic.', 'I reviewed the duplicated behavior and identified which parts were truly shared.', 'I moved common exception mapping into a global handler and kept endpoint-specific rules in their services.', 'The controllers became simpler, and new endpoints returned consistent errors.'], ['Nhiều controller lặp lại logic validation và response lỗi.', 'Tôi review hành vi bị lặp và xác định phần nào thực sự dùng chung.', 'Tôi chuyển mapping exception chung vào global handler và giữ rule riêng của endpoint trong service.', 'Controller đơn giản hơn và endpoint mới trả lỗi nhất quán.'], [['duplicated behavior', 'hành vi bị lặp lại'], ['global handler', 'bộ xử lý chung toàn ứng dụng'], ['endpoint-specific', 'riêng cho từng endpoint']]],
  ['Describe a time you improved the reliability of a background job.', 'Mô tả lần bạn cải thiện độ tin cậy của background job.', ['A nightly synchronization job sometimes stopped after processing only part of a dataset.', 'I checked the job logs and found that one invalid record stopped the entire batch.', 'I added per-record error handling, retry for transient failures, and a summary of failed records.', 'The job could continue safely, and the operations team could review failures the next morning.'], ['Job đồng bộ ban đêm đôi khi dừng sau khi chỉ xử lý một phần dữ liệu.', 'Tôi xem log và phát hiện một bản ghi sai làm dừng cả batch.', 'Tôi thêm xử lý lỗi theo từng bản ghi, retry lỗi tạm thời và báo cáo tổng hợp bản ghi thất bại.', 'Job tiếp tục chạy an toàn và nhóm vận hành có thể xem lỗi vào sáng hôm sau.'], [['background job', 'tác vụ chạy nền'], ['transient failure', 'lỗi tạm thời có thể tự hết'], ['failed record', 'bản ghi xử lý thất bại']]],
  ['Tell me about a time you had to learn a new technology quickly.', 'Kể về lần bạn phải học nhanh một công nghệ mới.', ['The project needed a file export feature, but I had not used the reporting library before.', 'I read the official examples and built a small prototype with representative data.', 'I reviewed memory usage and edge cases with a teammate before integrating it into the service.', 'We delivered the export safely, and I documented the setup for the rest of the team.'], ['Dự án cần tính năng xuất file nhưng tôi chưa dùng thư viện báo cáo đó.', 'Tôi đọc ví dụ chính thức và tạo prototype nhỏ với dữ liệu đại diện.', 'Tôi cùng đồng nghiệp review mức dùng bộ nhớ và trường hợp biên trước khi tích hợp vào service.', 'Chúng tôi bàn giao tính năng an toàn và tôi ghi tài liệu cấu hình cho cả nhóm.'], [['prototype', 'bản thử nghiệm nhỏ'], ['representative data', 'dữ liệu đại diện cho tình huống thật'], ['integrate', 'tích hợp']]],
  ['Describe a time a requirement changed during implementation.', 'Mô tả lần yêu cầu thay đổi khi bạn đang triển khai.', ['The client changed the export permission after development had started.', 'I clarified the new role rules and checked which endpoints and tests were affected.', 'I updated the authorization logic, added regression coverage, and explained the schedule impact.', 'The team delivered the revised behavior with the permission rules documented.'], ['Khách thay đổi quyền export sau khi quá trình phát triển đã bắt đầu.', 'Tôi làm rõ rule role mới và kiểm tra endpoint, test nào bị ảnh hưởng.', 'Tôi cập nhật logic phân quyền, thêm regression test và giải thích ảnh hưởng tiến độ.', 'Nhóm bàn giao hành vi mới cùng tài liệu về quy tắc quyền.'], [['schedule impact', 'ảnh hưởng đến tiến độ'], ['authorization logic', 'logic phân quyền'], ['document a rule', 'ghi lại một quy tắc']]],
  ['Tell me about a time you prevented a security issue.', 'Kể về lần bạn ngăn chặn một vấn đề bảo mật.', ['A user management endpoint was returning more fields than the screen needed.', 'I reviewed the response payload and noticed that internal account fields were included.', 'I created a dedicated response DTO and added a test to verify that sensitive fields were omitted.', 'The API exposed only the required data, and the response contract became clearer.'], ['Endpoint quản lý user trả về nhiều field hơn màn hình cần.', 'Tôi review payload và thấy có cả field nội bộ của tài khoản.', 'Tôi tạo response DTO riêng và thêm test xác nhận field nhạy cảm bị loại bỏ.', 'API chỉ trả dữ liệu cần thiết và contract response rõ ràng hơn.'], [['response payload', 'phần dữ liệu API trả về'], ['sensitive field', 'trường dữ liệu nhạy cảm'], ['omit a field', 'loại bỏ một trường khỏi kết quả']]],
  ['Describe a time you improved an API without changing its behavior.', 'Mô tả lần bạn cải thiện API mà không đổi hành vi bên ngoài.', ['A frequently used endpoint returned the correct data but performed several unnecessary queries.', 'I captured the existing response and measured the query count before making changes.', 'I replaced the entity loading with a projection and added a test for the response contract.', 'The client received the same fields while database work decreased.'], ['Endpoint được dùng nhiều trả đúng dữ liệu nhưng chạy nhiều query không cần thiết.', 'Tôi lưu lại response hiện có và đo số query trước khi thay đổi.', 'Tôi thay việc tải entity bằng projection và thêm test cho response contract.', 'Client vẫn nhận các field như cũ trong khi số truy vấn database giảm.'], [['response contract', 'quy ước cấu trúc response'], ['projection', 'truy vấn chỉ lấy các trường cần thiết'], ['query count', 'số lượng truy vấn']]],
  ['Tell me about a production incident you helped resolve.', 'Kể về sự cố production bạn từng hỗ trợ xử lý.', ['A production release caused a rise in failed requests for one customer workflow.', 'I checked the deployment timeline, application logs, and error rate to narrow down the change.', 'I helped roll back the release, then reproduced the issue in staging and fixed the configuration.', 'We restored the workflow and added a deployment check to catch the same configuration error.'], ['Một lần phát hành production làm tăng lỗi request ở một luồng khách hàng.', 'Tôi đối chiếu thời gian deploy, log ứng dụng và error rate để khoanh vùng thay đổi.', 'Tôi hỗ trợ rollback, sau đó tái hiện lỗi trên staging và sửa cấu hình.', 'Luồng được khôi phục và nhóm thêm bước kiểm tra deploy để phát hiện lại lỗi cấu hình.'], [['narrow down', 'thu hẹp phạm vi nguyên nhân'], ['roll back a release', 'quay lại bản phát hành trước'], ['restore a workflow', 'khôi phục luồng hoạt động']]],
  ['Describe a time you collaborated with QA to deliver a feature.', 'Mô tả lần bạn phối hợp với QA để bàn giao tính năng.', ['The team was adding bulk import, which had several validation and permission edge cases.', 'I shared the API contract and sample files with QA before the implementation was complete.', 'We reviewed invalid-row behavior together and added cases for duplicates and missing fields.', 'QA found issues early, and the release had fewer surprises.'], ['Nhóm thêm tính năng import hàng loạt với nhiều trường hợp biên về validation và quyền.', 'Tôi chia sẻ API contract và file mẫu với QA trước khi triển khai xong.', 'Chúng tôi cùng review cách xử lý dòng sai và thêm trường hợp trùng dữ liệu, thiếu field.', 'QA phát hiện vấn đề sớm và bản phát hành ít bất ngờ hơn.'], [['bulk import', 'nhập dữ liệu hàng loạt'], ['sample file', 'file dữ liệu mẫu'], ['invalid-row behavior', 'cách xử lý dòng dữ liệu sai']]],
  ['Tell me about a time you improved observability.', 'Kể về lần bạn cải thiện khả năng quan sát hệ thống.', ['When a scheduled job failed, the logs did not show which record caused the problem.', 'I traced the job flow and identified the context missing from each log entry.', 'I added a correlation ID, record identifier, and a summary metric without logging sensitive values.', 'The team could locate failed records faster while keeping personal data out of the logs.'], ['Khi scheduled job lỗi, log không cho biết bản ghi nào gây vấn đề.', 'Tôi lần theo luồng job và xác định context còn thiếu trong từng log entry.', 'Tôi thêm correlation ID, mã bản ghi và metric tổng hợp mà không ghi giá trị nhạy cảm.', 'Nhóm tìm bản ghi lỗi nhanh hơn mà không đưa dữ liệu cá nhân vào log.'], [['observability', 'khả năng theo dõi và hiểu trạng thái hệ thống'], ['correlation ID', 'mã theo dõi một request qua nhiều bước'], ['log entry', 'một dòng hoặc sự kiện log']]],
  ['Describe a time you disagreed with a technical proposal.', 'Mô tả lần bạn không đồng ý với một đề xuất kỹ thuật.', ['A proposal suggested caching all customer data to reduce database load.', 'I checked the freshness requirements and identified records that changed frequently.', 'I shared the trade-offs and proposed caching only reference data with a clear expiration policy.', 'The team reduced repeated reads without serving outdated customer information.'], ['Có đề xuất cache toàn bộ dữ liệu khách hàng để giảm tải database.', 'Tôi kiểm tra yêu cầu cập nhật và xác định các bản ghi thay đổi thường xuyên.', 'Tôi trình bày đánh đổi và đề xuất chỉ cache dữ liệu tham chiếu với chính sách hết hạn rõ ràng.', 'Nhóm giảm đọc lặp mà không trả thông tin khách hàng cũ.'], [['freshness requirement', 'yêu cầu dữ liệu phải mới đến mức nào'], ['expiration policy', 'chính sách hết hạn'], ['outdated information', 'thông tin đã cũ']]],
  ['Tell me about a time you had to estimate work with incomplete information.', 'Kể về lần bạn ước lượng công việc khi thông tin chưa đầy đủ.', ['A ticket requested a new approval flow but did not define all exception cases.', 'I listed the unknowns and asked the product owner about rejection, reassignment, and audit behavior.', 'I estimated the confirmed scope separately and called out the open questions as risks.', 'The team could plan the first release without hiding uncertainty in the estimate.'], ['Ticket yêu cầu luồng phê duyệt mới nhưng chưa định nghĩa các trường hợp ngoại lệ.', 'Tôi liệt kê điều chưa rõ và hỏi product owner về từ chối, giao lại và audit.', 'Tôi ước lượng riêng phạm vi đã xác nhận và nêu câu hỏi còn mở như rủi ro.', 'Nhóm có thể lên kế hoạch bản đầu mà không che giấu sự chưa chắc chắn trong estimate.'], [['incomplete information', 'thông tin chưa đầy đủ'], ['open question', 'câu hỏi chưa có lời giải'], ['call out a risk', 'nêu rõ một rủi ro']]],
  ['Describe a time you made a mistake and what you learned.', 'Mô tả lần bạn mắc lỗi và bài học rút ra.', ['I once merged a configuration change without checking how it behaved in the staging environment.', 'The deployment failed because a required secret name was different from my local setup.', 'I corrected the configuration, added a pipeline validation step, and documented the environment variables.', 'I now verify deployment assumptions in a shared environment before merging similar changes.'], ['Tôi từng merge thay đổi cấu hình mà chưa kiểm tra trên staging.', 'Deploy thất bại vì tên secret bắt buộc khác với cấu hình local.', 'Tôi sửa cấu hình, thêm bước validate vào pipeline và ghi tài liệu biến môi trường.', 'Giờ tôi xác minh giả định deploy trên môi trường dùng chung trước khi merge thay đổi tương tự.'], [['deployment assumption', 'giả định liên quan đến triển khai'], ['pipeline validation', 'bước kiểm tra trong pipeline'], ['shared environment', 'môi trường dùng chung']]],
  ['Tell me about a time you took ownership of a task.', 'Kể về lần bạn chủ động chịu trách nhiệm đến cùng cho một đầu việc.', ['An API change was delayed because the backend, frontend, and QA teams had different expectations.', 'I reviewed the ticket and arranged a short discussion to agree on the request and response behavior.', 'I updated the API contract, tracked the follow-up tasks, and shared progress with each team.', 'The teams integrated against the same contract and completed the feature without another handoff delay.'], ['Thay đổi API bị chậm vì backend, frontend và QA hiểu khác nhau.', 'Tôi xem ticket và tổ chức trao đổi ngắn để thống nhất hành vi request, response.', 'Tôi cập nhật API contract, theo dõi việc tiếp theo và chia sẻ tiến độ với từng nhóm.', 'Các nhóm tích hợp theo cùng contract và hoàn thành tính năng mà không bị chậm thêm do bàn giao.'], [['take ownership', 'chủ động chịu trách nhiệm'], ['handoff delay', 'chậm trễ do bàn giao công việc'], ['follow-up task', 'đầu việc cần tiếp tục sau đó']]],
  ['Describe a time you worked with a difficult technical constraint.', 'Mô tả lần bạn phải làm việc với một giới hạn kỹ thuật khó.', ['A legacy integration accepted only a fixed-width file and could not be changed before launch.', 'I mapped the external format to our internal DTO and documented the field length constraints.', 'I added validation and a preview step so users could fix invalid rows before submission.', 'The integration remained compatible while the support team received clearer error information.'], ['Một tích hợp cũ chỉ nhận file fixed-width và chưa thể thay đổi trước ngày ra mắt.', 'Tôi mapping format bên ngoài sang DTO nội bộ và ghi rõ giới hạn độ dài field.', 'Tôi thêm validation và bước preview để user sửa dòng sai trước khi gửi.', 'Tích hợp vẫn tương thích và nhóm hỗ trợ nhận được thông tin lỗi rõ hơn.'], [['legacy integration', 'tích hợp với hệ thống cũ'], ['fixed-width file', 'file có độ rộng trường cố định'], ['constraint', 'giới hạn kỹ thuật hoặc nghiệp vụ']]],
  ['Tell me about a time you improved a CI/CD pipeline.', 'Kể về lần bạn cải thiện pipeline CI/CD.', ['The pipeline took a long time because every job rebuilt the same dependencies.', 'I reviewed the job timings and found that dependency caching was not configured.', 'I added a cache with a safe key and kept security scanning and tests as required gates.', 'Build feedback became faster without skipping quality checks.'], ['Pipeline chạy lâu vì mỗi job đều build lại cùng dependency.', 'Tôi xem thời gian từng job và thấy chưa cấu hình cache dependency.', 'Tôi thêm cache với key an toàn và giữ security scan, test làm các bước bắt buộc.', 'Phản hồi build nhanh hơn mà không bỏ qua kiểm tra chất lượng.'], [['dependency cache', 'bộ nhớ đệm cho thư viện phụ thuộc'], ['quality gate', 'điều kiện chất lượng bắt buộc trước khi qua bước tiếp'], ['job timing', 'thời gian thực hiện từng job']]],
];

const makeInterview = ([prompt, promptVi, situation, sample, sampleVi, structure, words]) => ({ prompt, promptVi, situation, sample, sampleVi, structure, words });
const makeStandup = ([situation, yesterday, today, blocker, translations, words]) => ({ situation, yesterday, today, blocker, translations, words });
const makeClarify = ([situation, questions, customer, customerVi, next, nextEn, words]) => ({
  situation,
  options: [...questions.map(text => ({ text, good: true, why: 'Câu hỏi giúp làm rõ phạm vi, hành vi hoặc tiêu chí nghiệm thu trước khi triển khai.' })), { text: 'I’ll make an assumption and start coding without confirming it.', good: false, why: 'Tự giả định dễ dẫn đến triển khai sai mong đợi và phải làm lại.' }],
  customer, customerVi, next, nextEn, words,
});
const makeIncident = ([situation, firstCheck, secondCheck, riskyAction, model, modelVi, words]) => ({
  situation,
  investigation: [
    { text: firstCheck, good: true, why: 'Kiểm tra này thu thập bằng chứng trực tiếp từ dấu hiệu trong ticket hoặc log.' },
    { text: secondCheck, good: true, why: 'Đối chiếu thêm dữ liệu giúp khoanh vùng nguyên nhân trước khi sửa.' },
    { text: riskyAction, good: false, why: 'Thay đổi này vội vàng, có thể che nguyên nhân hoặc làm tăng tác động sự cố.' },
  ],
  model, modelVi, words,
});
const makeAnswerBuilder = ([prompt, promptVi, blocks, translations, words]) => ({
  prompt, promptVi, blocks, order: [0, 1, 2, 3], notes: ['Bối cảnh và vấn đề', 'Việc bạn chủ động làm', 'Kết quả hoặc bằng chứng', 'Bài học hay cải tiến tiếp theo'],
  model: blocks.join(' '), modelVi: translations.join(' '), words,
});

export const additionalItEnglishRounds = {
  interview: interview.slice(0, 14).map(makeInterview),
  standup: standup.map(makeStandup),
  clarify: clarify.slice(0, 16).map(makeClarify),
  incident: incidents.slice(0, 16).map(makeIncident),
  'answer-builder': answerBuilder.map(makeAnswerBuilder),
};
